<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import axios from 'axios';
import ClientExchangeSummary from '../components/clientExchange/ClientExchangeSummary.vue';
import ExchangeMatchStatus from '../components/clientExchange/ExchangeMatchStatus.vue';
import {exchangeRequestNeedsPlan,exchangeRequestPlanValid,exchangePersonalFitSummary} from '../navigation/clientExchangePolicy.js';
const props=defineProps({apiBase:String,sessionToken:String,userId:[Number,String],agencies:{type:Array,default:()=>[]},visible:{type:Boolean,default:true},listingId:[Number,String],agencyId:[Number,String]});
const agency=ref('all'),mode=ref('open'),search=ref(''),items=ref([]),requests=ref([]),detail=ref(null),message=ref(''),warnings=ref([]),loading=ref(false),opening=ref(false),sending=ref(false),error=ref(''),notice=ref('');
const busy=computed(()=>loading.value||opening.value||sending.value),filtered=computed(()=>items.value.filter(row=>!search.value||JSON.stringify([row.clientInitials,row.serviceType,row.agencyName,row.presentingProblems,row.message]).toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>fitRank(a)-fitRank(b)));
function fitRank(row){return {matched:0,eligible:1,blocked:2}[exchangePersonalFitSummary(row.viewerFit).state]??3;}
const warningsAcknowledged=computed(()=>(detail.value?.viewerFit?.adjustments||[]).every(warning=>warning.fingerprint&&warnings.value.includes(warning.fingerprint)));
const fitSummary=row=>exchangePersonalFitSummary(row.viewerFit);
const requestAvailable=computed(()=>detail.value?.viewerFit?.canRequest===true&&(!detail.value.isDemo||detail.value.demoRequestAllowed)&&['open','requested'].includes(detail.value.status)&&!requests.value.some(row=>row.status==='pending'&&Number(row.requestingProviderUserId)===Number(props.userId)));
let listVersion=0,openVersion=0,sendVersion=0,handledNotification='';const cache=new Map();
const request=(method,path,agencyId,data)=>axios({method,url:`${props.apiBase}/exchange${path}`,params:{agencyId},data,headers:{'X-Quick-View-Session':props.sessionToken},withCredentials:true});
async function load(force=false){if(!props.visible||!props.sessionToken)return;const key=`${agency.value}:${mode.value}`,cached=cache.get(key),current=++listVersion,token=props.sessionToken,selectedMode=mode.value;error.value='';if(cached){items.value=cached.items;if(!force&&Date.now()-cached.at<60000){loading.value=false;return;}}loading.value=true;
 const selected=props.agencies.filter(a=>agency.value==='all'||String(a.id)===String(agency.value));
 const results=await Promise.allSettled(selected.map(async a=>{const{data}=await request('GET',selectedMode==='requests'?'/my-requests':'/listings',a.id);return(data[selectedMode==='requests'?'requests':'listings']||[]).map(row=>({...row,agencyId:a.id,agencyName:a.name,agencyLogoUrl:a.logoUrl}));}));
 if(current!==listVersion||token!==props.sessionToken)return;const failed=results.filter(result=>result.status==='rejected');items.value=results.filter(result=>result.status==='fulfilled').flatMap(result=>result.value).filter(row=>selectedMode!=='open'||['open','requested'].includes(row.status));if(!failed.length)cache.set(key,{items:items.value,at:Date.now()});else{cache.delete(key);error.value=failed[0].reason.response?.data?.error?.message||'Some agency listings could not load. Refresh to try again.';}loading.value=false;
}
async function open(row){const current=++openVersion,token=props.sessionToken;error.value='';notice.value='';message.value='';warnings.value=[];detail.value=null;requests.value=[];opening.value=true;try{const{data}=await request('GET',`/listings/${row.listingId||row.id}`,row.agencyId);if(current!==openVersion||token!==props.sessionToken)return;if(!data.listing||Number(data.listing.agencyId)!==Number(row.agencyId))throw new Error('Listing agency mismatch');detail.value={...data.listing,agencyName:row.agencyName||props.agencies.find(a=>Number(a.id)===Number(row.agencyId))?.name};requests.value=data.requests||[];}catch(e){if(current===openVersion&&token===props.sessionToken)error.value=e.response?.data?.error?.message||'This listing is unavailable.';}finally{if(current===openVersion)opening.value=false;}}
function back(){openVersion++;detail.value=null;requests.value=[];opening.value=false;error.value='';}
async function send(){if(sending.value||!requestAvailable.value||!warningsAcknowledged.value||!exchangeRequestPlanValid(detail.value.viewerFit,message.value))return;const current=++sendVersion,token=props.sessionToken,listing=detail.value;sending.value=true;error.value='';try{await request('POST',`/listings/${listing.id}/requests`,listing.agencyId,{message:message.value.trim(),acknowledgedWarnings:warnings.value});if(current!==sendVersion||token!==props.sessionToken)return;notice.value='Your request was submitted to the referring team.';detail.value=null;cache.clear();void load(true);}catch(e){if(current!==sendVersion||token!==props.sessionToken)return;error.value=e.response?.data?.error?.message||'Your request could not be submitted.';if(e.response?.data?.fit&&detail.value?.id===listing.id){detail.value={...detail.value,viewerFit:e.response.data.fit};warnings.value=[];}}finally{if(current===sendVersion)sending.value=false;}}
function openNotification(){if(!props.visible||!props.listingId||!props.agencies.length)return;const selected=props.agencyId?props.agencies.find(a=>Number(a.id)===Number(props.agencyId)):props.agencies.length===1?props.agencies[0]:null;if(!selected)return;const key=`${selected.id}:${props.listingId}`;if(key===handledNotification)return;handledNotification=key;void open({id:props.listingId,agencyId:selected.id,agencyName:selected.name});}
watch([agency,mode],()=>{back();void load(true);});watch(()=>props.visible,value=>{if(value){void load();openNotification();}});watch(()=>props.sessionToken,()=>{listVersion++;openVersion++;sendVersion++;items.value=[];detail.value=null;requests.value=[];cache.clear();handledNotification='';loading.value=false;opening.value=false;sending.value=false;void load(true);openNotification();});watch(()=>[props.listingId,props.agencyId],openNotification);watch(()=>props.agencies,()=>{cache.clear();items.value=items.value.filter(row=>props.agencies.some(a=>Number(a.id)===Number(row.agencyId)));if(detail.value&&!props.agencies.some(a=>Number(a.id)===Number(detail.value.agencyId)))back();void load(true);openNotification();},{deep:true});onMounted(()=>{void load();openNotification();});onBeforeUnmount(()=>{listVersion++;openVersion++;sendVersion++;cache.clear();});
</script>
<template>
 <section class="mobile-exchange"><header><h2>Client Exchange</h2><button :disabled="busy" @click="detail?open(detail):load(true)">Refresh</button></header><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
 <p v-if="opening" role="status">Opening listing… <button @click="back">Cancel</button></p><template v-if="detail"><button @click="back">← Back</button><h3>{{detail.clientInitials || 'Client'}} · {{detail.serviceType}}</h3><p>{{detail.agencyName}} · {{detail.status}}</p><ClientExchangeSummary :listing="detail"/><ExchangeMatchStatus :fit="detail.viewerFit"/><p v-for="row in requests" :key="row.id">{{row.requestingProviderName || 'Provider request'}} · {{row.status}}</p><form v-if="requestAvailable" @submit.prevent="send"><p v-if="exchangeRequestNeedsPlan(detail.viewerFit)">Describe how you can address the availability or location differences (at least 20 characters).</p><label>Request details<textarea v-model="message" maxlength="2000" placeholder="Availability or adjustments you can offer"/></label><label v-for="warning in detail.viewerFit.adjustments || []" :key="warning.code" class="warning"><input v-model="warnings" type="checkbox" :value="warning.fingerprint"/>{{warning.message || warning.label || warning.code}}</label><button :disabled="sending||!warningsAcknowledged||!exchangeRequestPlanValid(detail.viewerFit,message)">{{sending?'Submitting…':'Request this client'}}</button></form><p v-else>Current access and matching requirements determine the available actions.</p></template>
 <template v-else><div class="filters"><select v-model="agency" aria-label="Client Exchange agency"><option value="all">All agencies</option><option v-for="a in agencies" :key="a.id" :value="String(a.id)">{{a.name}}</option></select><select v-model="mode" aria-label="Client Exchange status"><option value="open">Available clients</option><option value="all">All listings</option><option value="requests">My requests</option></select><input v-model="search" type="search" aria-label="Search Client Exchange" placeholder="Search clients or services"/></div><p v-if="busy && !items.length" role="status">Loading Client Exchange…</p><button v-for="row in filtered" :key="`${row.agencyId}:${row.id}`" class="listing" @click="open(row)"><img v-if="row.agencyLogoUrl" :src="row.agencyLogoUrl" alt=""/><span><strong>{{row.clientInitials || 'Client'}} · {{row.serviceType || 'Request'}}</strong><small>{{row.agencyName}} · {{row.status}}</small><span v-if="mode!=='requests'" class="personal-fit" :class="fitSummary(row).state"><strong>{{fitSummary(row).label}}</strong><small v-if="row.viewerFit?.matchScore!=null">Preference score {{row.viewerFit.matchScore}}%</small><small v-for="reason in fitSummary(row).reasons.slice(0,3)" :key="reason">{{reason}}</small><small v-if="fitSummary(row).reasons.length>3">+{{fitSummary(row).reasons.length-3}} more · Open for details</small></span></span><span>View ›</span></button><p v-if="!busy && !filtered.length">No listings in this view.</p></template>
 </section>
</template>
<style scoped>
.mobile-exchange{background:white;padding:16px;color:#203b56;min-width:0}.mobile-exchange header{display:flex;justify-content:space-between;align-items:center;gap:10px}h2{font-size:19px;margin:0}h3{font-size:16px}p{font-size:13px;line-height:1.5}.filters{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.filters>*{flex:1;min-width:0}.filters input{flex-basis:100%}button,input,select,textarea{font:inherit;color:inherit;border:1px solid #d5dfed;background:#f7faff;border-radius:9px;padding:10px;min-height:42px;box-sizing:border-box}input,select,textarea{font-size:16px}button{cursor:pointer}.listing{display:flex;align-items:center;gap:10px;width:100%;text-align:left;background:white;border-width:0 0 1px;border-radius:0;padding:16px 4px}.listing>span:first-of-type{flex:1}.listing img{width:28px;height:28px;object-fit:contain}.listing small{display:block;font-size:12px;color:#657d9c;margin-top:5px}form label{display:grid;gap:6px;margin:14px 0}textarea{min-height:100px;width:100%}.warning{display:flex;align-items:center}
.personal-fit{display:block;border-left:3px solid #a7b4c5;border-radius:5px;padding:7px 9px;margin-top:8px;background:#f5f7fa}.personal-fit>strong{font-size:12px}.personal-fit.matched{border-color:#3b9871;background:#eef8f2;color:#216147}.personal-fit.eligible{border-color:#c49c43;background:#fffaed;color:#765b20}.personal-fit.blocked{border-color:#bd6f73;background:#fff3f3;color:#8d383d}.personal-fit small{font-size:11px;color:inherit;margin-top:3px}
</style>
